UPDATE lessons SET title='Year 4, Week 28, Lesson 2: Designing a moving toy', data=json_patch(data,'{"child_mission":"Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWrite success criteria for a toy that spins a paper propeller for three seconds.\n\nFEEDBACK\ne.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria.\n\nWATCH FOR\nBuilding before criteria makes “success” only a feeling.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nProduce a design folio page: brief, criteria, two sketched options, chosen mechanism with reasons.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science and Technology","learning_intention":"Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building.","lesson_number":2,"lesson_role":"Apply and make","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["ST2-DDT-01"],"parent_notes":"Parent: Marking guidance for the independent task: Produce a design folio page: brief, criteria, two sketched options, chosen mechanism with reasons. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new object/context, two named observations, claim about design linked to that evidence.\n\nParent: Written model 2: Sample misconception: Building before criteria makes “success” only a feeling.. Correction: e.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria. with evidence.\n\nParent: Likely misconception: Building before criteria makes “success” only a feeling. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses design. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about design, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Accept a new example with named observations and a claim–evidence link about design. Reject title-only labels with no observation. / Accept a misconception plus corrected claim and evidence reason for design. Reject wording changes that leave the same error..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for design. The other choices miss a key step or use a common mistake.","options":["e.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria","Building before criteria makes “success” only a feeling","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Write success criteria for a toy that spins a paper propeller for three seconds. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"This is the misconception to avoid for design; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building","e.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria","Careful use of toy and explain why it matters with clear evidence","Building before criteria makes “success” only a feeling"],"question":"Which statement is a common mistake when working with design?","type":"multiple_choice"},{"correct_index":0,"explanation":"Understanding is shown by new evidence and a named toy and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Apply design to new material and name the toy and explain why it matters used","Repeat the worked example wording with no new evidence","Building before criteria makes “success” only a feeling","Name toy and explain why it matters only, without linking it to design"],"question":"Which response best applies design with new evidence?","type":"multiple_choice"},{"correct_index":0,"explanation":"Trustworthy science claims rest on observable evidence linked to the claim. The other choices miss a key step or use a common mistake.","options":["Use observable features or measurements as evidence, not appearance alone","Decide from which object looks most exciting","Copy a label from the lesson title with no observation","Building before criteria makes “success” only a feeling"],"question":"New examples: a charging phone, a nesting bird, a glass marble, a fallen dry leaf. Which claim about design is most trustworthy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Science claims need named observations linked to the claim. The other choices miss a key step or use a common mistake.","options":["A longer story with no observation","A label copied from the title with no evidence","Building before criteria makes “success” only a feeling","A named observation plus how it supports the claim"],"question":"Which record best supports a science claim about design?","type":"multiple_choice"},{"correct_index":1,"explanation":"The strongest choice applies the taught idea about design with evidence. The other choices miss a key step or use a common mistake.","options":["Ignore measurements and decide by which looks nicer","e.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria","Building before criteria makes “success” only a feeling","Change several conditions at once so something happens faster"],"question":"Using this science idea — Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a — which choice is strongest?","type":"multiple_choice"},{"correct_index":1,"explanation":"Fair tests change one variable, control the rest, and use recorded evidence. The other choices miss a key step or use a common mistake.","options":["Ignore measurements and decide by which looks nicer","Change one variable and keep the other conditions the same","Change several conditions at once so something happens faster","Stop early when you like the first result"],"question":"Which investigation design best tests an idea about design?","type":"multiple_choice"},{"correct_index":1,"explanation":"Scientific predictions stay open to new observations rather than protecting a first guess. The other choices miss a key step or use a common mistake.","options":["Results that disagree with the first guess should be discarded","If the observed feature changes, the claim about design should change with it","Any exciting story about the object must be true","Building before criteria makes “success” only a feeling"],"question":"Which prediction about design can be checked with evidence?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept a new example with named observations and a claim–evidence link about design. Reject title-only labels with no observation.","question":"Investigate or describe a fresh example (not the worked objects) that uses design. Record evidence and explain how it supports your claim.","sample_answer":"Sample: new object/context, two named observations, claim about design linked to that evidence.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception plus corrected claim and evidence reason for design. Reject wording changes that leave the same error.","question":"Name one science misconception about design, correct it with evidence, and say why the correction works.","sample_answer":"Sample misconception: Building before criteria makes “success” only a feeling.. Correction: e.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria. with evidence.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-sci-y4-w28-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise design.","Read the mission before you start observing or testing.","Keep the property or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations.","Say what each observation shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Engineering and Design","success_criteria":["I can use design with a specific example from this lesson.","I can identify toy and explain why it matters.","I can practise motion independently on a new prompt.","I can notice criteria needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building"],"question":"Which choice best applies this lesson idea about design with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nBrief: toy that rolls 1 m then stops a marble. Criteria: safe materials; rolls straight; marble releases. Sketch wheel/axle + stop lever ideas.\n\nTRY FIRST\nWrite success criteria for a toy that spins a paper propeller for three seconds.\n\nFEEDBACK\ne.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria.","explain":"Designing a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Building before criteria makes “success” only a feeling. Correct the claim or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Moving toy design.","caption":"Criteria before build.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Brief</text><text x=\"28\" y=\"78\">criteria</text><text x=\"358\" y=\"42\">Sketch options</text><text x=\"358\" y=\"78\">choose mechanism</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation matters most.","who":"pip"},{"text":"Name the observations, properties or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Brief: toy that rolls 1 m then stops a marble. Criteria: safe materials; rolls straight; marble releases. Sketch wheel/a Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation matters most.\nJuno: Name the observations, properties or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Brief: toy that rolls 1 m then stops a marble. Criteria: safe materials; rolls straight; marble releases. Sketch wheel/a Then write your own evidence."}}]},{"check":{"correct_index":3,"explanation":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Make the science idea visible: name the observation, source or example you used and say why it supports the claim"],"question":"Which choice best applies this lesson idea about design with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nBrief: toy that rolls 1 m then stops a marble. Criteria: safe materials; rolls straight; marble releases. Sketch wheel/axle + stop lever ideas. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show science thinking. Correct the claim or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"Justified choice.","caption":"Design folio.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Folio page</text><text x=\"28\" y=\"78\">two options</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">build then invent criteria</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally incorrect claim as a comparison.","options":["A guess with no evidence","A claim unrelated to the observation or test","Use an intentionally incorrect claim as a comparison","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about design with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nBuilding before criteria makes “success” only a feeling. Here is a more productive model: Brief: toy that rolls 1 m then stops a marble. Criteria: safe materials; rolls straight; marble releases. Sketch wheel/axle + stop lever ideas.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\ne.g. spins ≥3 s; safe edges; works three trials — any clear measurable criteria.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Building before criteria makes “success” only a feeling. Correct the claim or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the same science idea on a new place, person, source or context, not a copy of the worked example.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Use the same science idea on a new place, person, source or context, not a copy of the worked example"],"question":"Which choice best applies this lesson idea about design with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nDesigning a moving toy starts with a purpose, success criteria and a mechanism choice, then a sketch before building. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different evidence.","explain":"Use the same science idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 4, Week 28, Lesson 2: Designing a moving toy","unit_number":6,"unit_title":"Mechanisms and systems","week":28,"week_in_unit":3,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nBrief: toy that rolls 1 m then stops a marble. Criteria: safe materials; rolls straight; marble releases. Sketch wheel/axle + stop lever ideas.\n\nWrite what makes this example accurate, naming the observations, properties or test steps used.","worked_visuals":[{"alt":"Moving toy design.","caption":"Criteria before build.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Brief</text><text x=\"28\" y=\"78\">criteria</text><text x=\"358\" y=\"42\">Sketch options</text><text x=\"358\" y=\"78\">choose mechanism</text></g></svg>"},{"alt":"Justified choice.","caption":"Design folio.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Folio page</text><text x=\"28\" y=\"78\">two options</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">build then invent criteria</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-sci-y4-w28-l2' AND family_id IS NULL;
